mapper.select:
SELECT r.id, r.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, r.points_cost AS pointsCost, r.face_value AS faceValue, r.card_code AS cardCode, r.status, r.admin_user_id AS adminUserId, r.admin_remark AS adminRemark, r.create_time AS createTime, r.fulfill_time AS fulfillTime FROM bus_jd_redeem r LEFT JOIN sys_user u ON u.user_id = r.user_id WHERE r.is_deleted = 0
AND r.status = #{status}
ORDER BY r.create_time DESC
